/**
 * Lead changes are their own permission. `leadId: null` clears the lead; any
 * other value must be an active member of this organization who could
 * themselves `project:update` it.
 */
export async function changeProjectLead(
  actor: Actor,
  input: ChangeProjectLeadInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:change_lead", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.leadId !== null) {
    const candidate = await resolveActor(input.leadId, input.orgId);
    if (!candidate) {
      throw new NotFoundError("Member", input.leadId);
    }
    assertCan(candidate, "project:update", projectResource(project));
  }

  return projectRepo.updateProject({
    orgId: input.orgId,
    projectId: input.projectId,
    leadId: input.leadId,
  });
}

