describe("project:change_lead permission", () => {
  const project = (leadId: typeof ALICE | typeof BOB | null): PermissionResource => ({
    kind: "project",
    orgId: ORG_A,
    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
    visibility: "org",
    leadId,
  });

  it("requires admin and escalates for the current lead", () => {
    expect(ROLE_MATRIX["project:change_lead"]).toBe("admin");

    const ledByAlice = project(ALICE);
    expect(can(makeActor({ role: "owner", userId: BOB }), "project:change_lead", ledByAlice)).toBe(
      true,
    );
    expect(can(makeActor({ role: "admin", userId: BOB }), "project:change_lead", ledByAlice)).toBe(
      true,
    );
    expect(can(makeActor({ role: "member", userId: BOB }), "project:change_lead", ledByAlice)).toBe(
      false,
    );
    expect(can(makeActor({ role: "viewer", userId: BOB }), "project:change_lead", ledByAlice)).toBe(
      false,
    );
    expect(
      can(makeActor({ role: "viewer", userId: ALICE }), "project:change_lead", ledByAlice),
    ).toBe(true);
    expect(
      can(makeActor({ role: "member", userId: ALICE }), "project:change_lead", ledByAlice),
    ).toBe(true);
    expect(can(makeActor({ role: "viewer", userId: ALICE }), "project:change_lead", project(null))).toBe(
      false,
    );
  });
});

